      "Տոլմային բնորոշը ոչ թե բաղադրությունն է, այլ պատրաստելու եղանակը։ Բրինձը, սոխն ու առատ կանաչին՝ գառան կամ տավարի աղացած մսով կամ առանց դրա, փաթաթում են խաղողի կամ կաղամբի տերևի մեջ, կամ լցնում միջուկը հանած պղպեղի, սմբուկի, լոլիկի ու սերկևիլի մեջ։ Հետո տոլման խիտ շարում են կաթսայում, վրան ծանրություն դնում և դանդաղ եփում։ Անունը գալիս է «լցվել» նշանակող թյուրքական բայից։ Անմիս տարբերակը՝ պասուց տոլման, պատրաստում են լոբով, սիսեռով, ոսպով և հատիկեղենով, մատուցում սառը և ուտում պահքի օրերին։ Հայկական տներում տոլման հավաքույթների ուտեստ է, ոչ թե ամենօրյա ճաշ, և հարյուրավոր տերև փաթաթելը ընդհանուր գործ է։ Եղանակը հին է և տարածված ողջ տարածաշրջանում՝ ազգակից անուններով։ ՅՈՒՆԵՍԿՕ-ի 2017 թվականի ընդգրկման հայտը ներկայացրել է Ադրբեջանը, և այն արձանագրում է կենդանի ավանդույթ, ոչ թե ուտեստի ծագումը։",
    intro:
      "Տոլման բրնձի, սոխի, կանաչիի և հաճախ աղացած մսի լցոն է, որը փաթաթում են տերևների մեջ կամ լցնում միջուկը հանած բանջարեղենի մեջ ու դանդաղ եփում։ Այն պատրաստում են ողջ Կովկասում, Անատոլիայում, Իրանում և Արևելյան Միջերկրականում, և նրա բոլոր անունները ծագում են նույն բայից։ Հայկական տներում տոլման հավաքույթների ուտեստ է, ոչ թե արագ ամենօրյա ճաշ, և ունի անմիս տարբերակ՝ պահքի համար։ 2017 թվականին ՅՈՒՆԵՍԿՕ-ն Ներկայացուցչական ցանկում ընդգրկեց տոլմա պատրաստելու ավանդույթը։ Հայտը ներկայացրել էր Ադրբեջանը, և մենք դա չենք շրջանցում, որովհետև այն, թե ինչպես են հասկանում այդ ընդգրկումը, ինքնին այս ուտեստի պատմության մի մասն է։",
