    summary:
      "Հարիսան եփում են կորկոտից՝ մաքրված ցորենից, և հավի կամ գառան մսից։ Դրանք ժամերով եփում ու խառնում են, մինչև միսը լրիվ քայքայվի, ցորենը բացվի, և ամբողջը դառնա մեկ թանձր զանգված, ոչ թե կտորներով ապուր։ Հարիսայի ստուգումը նրա թանձրությունն է. լավ եփած հարիսան գդալից պոկվում է մեկ կտորով։ Մատուցելուց առաջ վրան հալած կարագ են լցնում, իսկ քիմիոնը կամ պղպեղը դնում են առանձին։ Քիչ բանով այն կշտացնում է շատ մարդու, դրա համար էլ հարիսան համայնքի և եկեղեցու առիթների ուտեստ է, ոչ թե մեկ ընտանիքի սեղանի։ Գրավոր վկայությունները հասնում են Բաղդադի X դարի խոհարարական ժողովածուին, և ազգակից անուններով նման ուտեստներ պատրաստում են ամբողջ Մերձավոր Արևելքում։ Իսկ ամենահայտնի հայկական առիթը շատ ավելի նոր է. ամեն սեպտեմբեր Արմավիրի Մուսալեռ գյուղում հիշում են 1915 թվականի Մուսա լեռան դիմադրությունը, և կաթսաները խառնում են ամբողջ գիշեր։",
    intro:
      "Հարիսան կորկոտ և միս է, որոնք միասին ժամերով եփում ու խառնում են, մինչև դրանք այլևս հնարավոր չլինի իրարից տարբերել։ Այն նուրբ ուտեստ չէ և երբեք էլ այդպիսին չի եղել։ Քիչ բանով կշտացնում է շատ մարդու, իսկ մեծ կաթսան կարող է եփվել ամբողջ գիշեր։ Գրավոր վկայությունները հասնում են Բաղդադի X դարի խոհարարական ժողովածուին, որտեղ հարիսան հիշատակվում է որպես ծեծած ցորենով ու մսով ուտեստ։ Իսկ ամենահայտնի հայկական առիթը շատ ավելի նոր է. ամեն սեպտեմբեր Արմավիրի Մուսալեռ գյուղում հիշում են 1915 թվականի Մուսա լեռան դիմադրությունը։",
