      "Գաթան անուշ թխվածք է, և նրա լցոնն իր անունն ունի՝ խորիզ։ Խորիզը կարագով ու շաքարով տրորած ալյուր է. այն մնում է փշրուն, իսկ թխվելիս հալվում ու միանում է խմորին։ Խմորի մեջ կարագ են դնում, հաճախ նաև մածուն կամ թթվասեր։ Թխելուց առաջ վրան ձու են քսում ու նախշ անում, և այդ նախշը նաև թույլ չի տալիս, որ մակերեսն ուռչի։ Գաթան ստացվում է ավելի չոր, քան խոնավ, և հենց դրա շնորհիվ երկար է մնում ու լավ դիմանում ճանապարհին։ Ամբողջական, փաթեթավորված գաթան հյուր գնալիս սովորական նվեր է, իսկ վանքերի մուտքի մոտ վաճառվող նախշազարդ կլոր գաթաները շատերի հիշողության մեջ գաթայի գլխավոր պատկերն են։ Մնացած ամեն ինչ գրեթե փոխվում է տեղից տեղ։ Գաթան կարող է լինել սեղանի չափ մեծ շրջան կամ ափի մեջ տեղավորվող գլանիկ։ Շատ ընտանիքներ իրենց նախշն ունեն, իսկ ընկույզով տարբերակը, որ թխում են հարավում և Իրանի հայերը, հաճախ կոչվում է նազուկ։",
    intro:
      "Գաթան անուշ խմորեղեն է, և նրա լցոնն իր անունն ունի՝ խորիզ։ Խորիզը կարագով ու շաքարով տրորած փշրուն ալյուր է, որը թխվելիս հալվում ու միանում է խմորին։ Սրանից բացի՝ գրեթե ամեն ինչ փոփոխական է։ Գաթան կարող է լինել սեղանի չափ մեծ շրջան կամ ափի մեջ տեղավորվող գլանիկ, հարթ կամ խիտ նախշազարդ։ Այն թխում են տոնի համար, տանում են որպես նվեր կամ պարզապես ուտում կեսօրվա սուրճի հետ։ 2018 թվականին Սմիթսոնյան ժողովրդական մշակույթի փառատոնի հայկական ծրագրում ցուցադրված անուշեղենների մեջ գաթա էլ կար։",
