    summary:
      "Ղափաման ամբողջական դդում է։ Այն բացում են կոթի կողմից, մաքրում կորիզներից և լցնում կիսաեփ բրնձով, որին խառնում են չիր, չամիչ, ընկույզ կամ նուշ, կարագ, մեղր և դարչին։ Հետո դդումը փակում են իր իսկ կափարիչով և դանդաղ թխում, մինչև միջուկը փափկի։ Այն սեղան են բերում ամբողջական և կտրում բնական ակոսների երկայնքով, որ բացվի դեպի դուրս. ղափաման պատրաստում են մեծ մասամբ հենց այդ պահի համար։ Ղափաման մատուցում են ճաշի վերջում՝ անուշ ուտեստների հետ, և այն հատկապես կապվում է Սուրբ Ծննդի ու Նոր տարվա սեղանների հետ։ Ընտանիքներն այն պահում էին տոների համար, որովհետև ընկույզն ու չիրը թանկ էին, այնպես որ նրա տոնական բնույթը տնտեսական ծագում ունի։ Ղափամայի մասին ժողովրդական երգը հաճախ են երգում հայկական հավաքույթներին։ Այս ուտեստը չի կարող շատ հին լինել. Cucurbita ցեղի բոլոր դդումներն Ամերիկայից են, ուստի ղափաման կարող էր հայտնվել միայն դդումը Հին աշխարհ հասնելուց հետո։",
