      "Խաշը արգանակ է. տավարի տոտիկները պարզ ջրում եփում են գրեթե ամբողջ գիշեր, իսկ ձմռան առավոտյան մատուցում եռման տաք ու անաղ։ Ամեն մեկն իր ամանը ինքն է համեմում՝ սխտորով, աղով և փշրած չոր լավաշով, և հենց դրա համար խաշն ավելի շուտ սեղան է, քան ափսե։ Սովորույթը խաշը կապում է ցուրտ ամիսների և վաղ ժամի հետ։ Իսկ բոլոր վկայությունները ամենից առաջ համաձայն են մի բանում՝ խաշը մենակ չեն ուտում։ Անգլերենում խաշի մասին ամենից հաճախ երկու բան են կրկնում՝ որ այն շատ հին է ու անփոփոխ, և որ փրկում է խումհարից։ Հենց այս երկուսն են, որ վկայությունները ամենաքիչն են հաստատում։",
    intro:
      "Խաշն այն է, ինչ ստացվում է, երբ կենդանու ամենակոշտ մասերին բավական ժամանակ ես տալիս։ Տավարի տոտիկները մաքրում են, երկար ժամեր պահում սառը ջրում, ապա եփում միայն ջրով, մինչև արգանակը թանձրանա դրանցից անջատված նյութից, իսկ միսը պոկվի ոսկորից։ Գրեթե մի ամբողջ գիշերվա աշխատանք՝ լուսաբացին ուտելու համար։ Խաշը սեղան է գալիս եռման տաք ու չհամեմված, և սեղանի շուրջ ամեն մեկն իր ամանը ինքն է համեմում՝ սխտորով, աղով և փշրած չոր հացով։ Ուտելիքն այսքան պարզ է։ Եղանակը, ժամը, կենացներն ու ընկերակցությունը այն սովորույթն են, որ ձևավորվել է դրա շուրջ, և այս հոդվածը հիմնականում այդ սովորույթի մասին է։",
