      "Մածունը կաթ է, որը կաթնաթթվային բակտերիաները թթվեցնում են այնքան, որ այն մակարդվում է ու դառնում թանձր, թթու մթերք, որ գդալով են ուտում։ Այն ուտում են մաքուր կամ հացով, բայց մածունը նաև այն հիմքն է, որի վրա կառուցված է խոհանոցի մեծ մասը։ Ջրով նոսրացրած՝ այն ըմպելիք է, եփած՝ ապուր, քամած ու աղած՝ պաշար, իսկ չորացրած՝ կարծր ու թթու գնդիկներ, որոնք տարիներ են դիմանում։ Ամեն նոր մածուն սկսում են նախորդի մի մասով, և դրա համար ավանդական մածունը կրում է իր տեղի մանրէները, ոչ թե գնված մերանի։ Հայկական և վրացական ավանդույթները նույն մթերքն են երկու անունով, և երկու երկրների մանրէաբանները դրանք ուսումնասիրել են միասին։ Բառը բնիկ հայերեն է և հին։ Թե որքան հին է մթերքն իր այսօրվա տեսքով, առանձին հարց է, և վկայությունները դրան պատասխան չեն տալիս։",
    intro:
      "Մածունն այն է, ինչ դառնում է կաթը, երբ ճիշտ բակտերիաներին թույլ են տալիս աշխատել։ Բակտերիաները կաթի շաքարը վերածում են թթվի, թթուն խախտում է սպիտակուցի կայունությունը, և ամբողջ ամանը մակարդվում է։ Ստացվում է թանձր, թթու, գդալով ուտելու մթերք, որը կաթից շատ ավելի երկար է պահվում։ Ամբողջ փոխակերպումն այսքան է։ Հայկական տներում դա արել են շատ երկար ժամանակ և ամենապարզ ձևով՝ երեկվա մածնից մի գդալ պահում են՝ վաղվանը սկսելու համար։ Սա այս բաժնի առաջին հոդվածն է ոչ թե պատրաստի ուտեստի, այլ հիմնական մթերքի մասին։ Մածունն ուտում են առանձին, բայց դրանից են պատրաստում նաև հայկական խոհանոցի զգալի մասը։",
