          "Հայտնի է նաև, թե ով էր այն այնտեղ պատրաստում։ Կեսարիայում այս առևտուրը գերազանցապես հայերի ձեռքում էր. տասնիններորդ դարի նկարագրությունները խոսում են արտադրության ու վաճառքի մեջ հայերի գերիշխանության մասին, մինչդեռ քաղաքի հույներն ու թուրքերը պաստրմա պատրաստում ու ուտում էին տանը։ Պատմաբան Ֆիլիպ Մանսելը հիշատակում է հայերի, որոնք տասնյոթերորդ դարից ի վեր Կոստանդնուպոլսում պաստրմա էին վաճառում։ Այդ աշխարհից մնացած ամենահայտնի հետքը ոչ թե ավանդազրույց է, այլ ձեռնարկություն։ Գրիգոր Ապիկօղլուն 1910 թվականին Կեսարիայում հիմնեց պաստրմայի իր գործը, 1920-ին արտադրությունը տեղափոխեց Կոստանդնուպոլիս, և ընկերությունը դարձավ Թուրքիայի Հանրապետության առաջին համապետական մսի ընկերությունը։",
