          "Երկուսն էլ կարող են ճիշտ լինել, որովհետև այստեղ որոշողը գինն ու երկար պահվելն են, ոչ թե առիթը։ Բաստուրման թանկ մթերք է. նիհար տավարի մեծ կտորը չորանալիս զգալիորեն քաշ է կորցնում, ապա շաբաթներով պահվում մինչև վաճառքը։ Այդ պատճառով այն գնում են քիչ-քիչ և կտրում բարակ։ Իսկ խնայողաբար կտրվող մթերքը քիչ քանակով կարող է լինել սովորական նախաճաշ, առատ քանակով՝ առատաձեռնության նշան, և դրանից այն չի փոխվում։",
