        paragraphs: [
          "Բաստուրման այս կամ այն ձևով կա հայկական, թուրքական, հունական, արաբական, քրդական, բուլղարական, եգիպտական և ադրբեջանական խոհանոցներում, և այդ բոլորում էլ պատրաստում են նրա տարբերակները։ Համացանցի սիրելի հարցին՝ ո՞վ է այն հորինել, վկայություններով հիմնավորված պատասխան չկա, և այդ վերնագրով վեճերը գրեթե միշտ ուտեստից բացի ուրիշ բանի մասին են։ Այս հոդվածն այս հարցում կողմ չի բռնում, որովհետև դրա համար անհրաժեշտ կլինեին աղբյուրներ, որոնք գոյություն չունեն։",
          "Այն հարցերը, որոնց կարելի է պատասխանել, ավելի նեղ են, բայց ավելի լավը։ Հայերենն ունի աղած-չորացրած մսի իր բառը, որը վկայված է հինգերորդ դարում և անցել է ևս երկու լեզվի։ Այս արհեստով ամենահայտնի քաղաքում հայերն էին այդ առևտրի փաստագրված վարպետները։ 1915 թվականից հետո հայերը արհեստը դուրս բերեցին Անատոլիայից և պահեցին կես տասնյակ երկրներում, և հենց դրա համար Լոս Անջելեսի խանութը կարող է իր գործի ակունքները հետևել Լիբանանով մինչև Հայաստան։ Սա ինքնատիպ և լավ վկայված հայկական ավանդույթ է տարածաշրջանի ընդհանուր պատմության ներսում, և կարևոր լինելու համար նրան գյուտի հավակնություն պետք չէ։",
          "Երկու հարևան ուտեստ էլ արժե հիշել՝ այս մեկի սահմանները հստակ գծելու համար։ Սուջուխը՝ չոր համեմված երշիկը, հայկական նախաճաշի ամեն նկարագրության մեջ բաստուրմայի կողքին է, բայց այլ եղանակով է պատրաստվում. միսն աղացում և լցնում են թաղանթի մեջ, ոչ թե պահում ամբողջական կտորով։ Այն այստեղ դեռ իր հոդվածը չունի։ Իսկ պաստրամին բաստուրմայի լեզվական ազգականն է, ոչ թե սերունդը։ Թուրքական բառը ռումիներենում դարձավ pastramă և տասնիններորդ դարի վերջին ռումինացի հրեա գաղթականների հետ հասավ Նյու Յորք, որտեղ ուտեստն ինքը նորից ստեղծվեց՝ կրծքամսից, աղաջրով և ծխով։ Բաստուրման պաստրամի չդարձավ։ Երկուսն էլ սերում են «սեղմել» նշանակող նույն բառից, իսկ հետո գնացին տարբեր ճանապարհներով։",
        ],
