      "Մսով լցոնված խմորի փոքրիկ բաց նավակներ, որոնք թխում են, մինչև եզրերը կարծրանան, ապա վրան լցնում արգանակ ու սխտորով մածուն։ Ամբողջ տարածաշրջանում պատրաստվող ուտեստ և նրա հայկական ձևը։",
    metaDescription:
      "Հայկական մանթի՝ բաց ձևով թխվող փոքրիկ խմորագնդեր արգանակով ու սխտորով մածունով. ինչով է առանձնանում այս ձևը և ինչի վրա են հենվում ծագման պատմությունները։",
    summary:
      "Մանթին մսով լցոնված փոքրիկ խմորագունդ է, և նրա հայկական ձևը հեռվից է ճանաչվում։ Խմորը չեն փակում, այլ սեղմում են բաց նավակի տեսքով, կանգնած շարում սկուտեղին և թխում, մինչև բաց մնացած խմորը կարմրի ու կարծրանա։ Հետո վրան լցնում են արգանակ և սխտորով մածուն։ Այս ձևն ամենից առաջ արևմտահայ խոհանոցինն է՝ Այնթապի, Մարաշի ու Կիլիկիայի դաշտի, ինչպես նաև նրանցից սերող սփյուռքյան համայնքների՝ Հալեպում, Բեյրութում, Լոս Անջելեսում ու Բոստոնում։ Մանթի կա նաև հայերից շատ հեռու՝ չինական մանթոուից մինչև Կենտրոնական Ասիա և թուրքական մանթը ձգվող մեծ ընտանիքում։ Իսկ տարածված պատմությունը, թե հայերն այն ստացել են մոնղոլներից XIII դարի Կիլիկիայում, գալիս է մի նոր գրքից, ոչ թե միջնադարյան աղբյուրից։ Աղբյուրները հաստատում են այլ բան՝ ընդհանուր ուտեստի ինքնատիպ հայկական մշակումը և անսովոր լավ փաստագրված պատմությունը այն մասին, թե ինչպես այն դուրս բերվեց Անատոլիայից ու պահպանվեց։",
    intro:
      "Աշխարհի գրեթե բոլոր խմորագնդերը փակ են։ Խմորը ծալում են լցոնի վրա և կպցնում եզրերը, իսկ հետո՝ եփեն, գոլորշու վրա պատրաստեն թե տապակեն, գործ ունեն փակ ծրարի հետ։ Հայկական մանթին բաց է մնում։ Խմորի փոքրիկ քառակուսու երկու կողմերը սեղմում են մի քիչ մսի շուրջ, ծայրերը թողնում բաց, և վառարան է մտնում ոչ թե փակ ծրարներով կաթսա, այլ փոքրիկ բաց նավակներով սկուտեղ։ Չոր տաքությունն անում է այն, ինչ ջուրը երբեք չէր կարող. վեր ցցված եզրերը կարմրում ու փխրուն են դառնում, մինչ լցոնը եփվում է ներսում։ Հետո տաք արգանակը լցնում են ուղիղ սկուտեղի մեջ, վրան դնում սխտորով հարած մածուն, և ուտեստը սեղան է հասնում միանգամից երեք տարբեր զգացողությամբ՝ խրթխրթան, փափուկ և սառը։ Այս հոդվածն այդ ձևի մասին է՝ ինչ է այն, որտեղից է, և որքանով են ճիշտ նրա մասին սովորաբար պատմվող պատմությունները։",
