        paragraphs: [
          "Խմորը պարզ է՝ ցորենի ալյուր և ջուր, սովորաբար նաև ձու. այն բացում են շատ բարակ և կտրում փոքր քառակուսիներով։ Խմորն անթթխմոր է, և դա այստեղ ավելի կարևոր է, քան այլ ուտեստներում. թթխմորով խմորը կուռչեր ու կփափկեր՝ կարծրանալու փոխարեն։ Այստեղ խմորից նրբություն չի պահանջվում. պետք է, որ այն չորանա և ձևը պահի, իսկ շատ բարակ լինելու շնորհիվ այն հասցնում է դա անել այնքան ժամանակում, որքան պետք է լցոնին եփվելու համար։",
          "Լցոնն աղացած միս է՝ սոխով ու համեմունքներով, և միսն ավելի շատ տարբերվում է տնից տուն, քան որևէ կանոնով։ Հին արևմտահայ վկայություններում սովորական է գառան միսը, և այն այսօր էլ հիմնականն է լևանտյան սփյուռքում։ Այսօրվա ամերիկյան ու հայաստանյան խոհանոցներում տավարի միսն առնվազն նույնքան տարածված է, իսկ երկուսի խառնուրդը սովորական բան է։ Սոխը գրեթե միշտ կա, իսկ համեմունքներից են աղը, պղպեղը, մաղադանոսը և հաճախ մի տաքացնող համեմ, օրինակ՝ անուշաբույր պղպեղ կամ չամանասերմ։ Կան նաև ոսպով կամ սիսեռով բուսական տարբերակներ, և դրանք պատրաստում են նույն մարդիկ, որոնք մսով մանթի էլ են պատրաստում։",
          "Թխելն է այստեղ որոշում ուտեստի բնույթը, և պատճառը սովորական սննդագիտությունն է։ Չոր տաքությունը ջուրը դուրս է քշում բացված խմորից, և նրա մակերեսը տաքանում է եռման կետից շատ ավելի։ Այդ ժամանակ խմորի շաքարներն ու սպիտակուցները կարմրում են, իսկ խմորը կարծրանում է։ Ջրում կամ գոլորշու վրա եփվող խմորագունդը ոչ մեկին, ոչ մյուսին չի հասնում, որովհետև նրա մակերեսը մնում է թաց և ջրի ջերմաստիճանից չի բարձրանում։ Ահա թե ինչու են բաց ձևն ու վառարանը միասին։ Բաց վերևը չոր օդին է տալիս խմորի հնարավորինս մեծ մասը, և արդյունքը մի ուտեստ է, որն իսկապես խրթխրթան է դեռ նախքան վրան որևէ բան կլցնեն։",
        ],
