          "Հայաստանի Հանրապետությունում պատկերն այլ է և բավական որոշակի։ Մանթին այստեղ հասանելի է ու հայտնի, բայց այն հայկական լեռնաշխարհի խոհանոցի սովորական ուտեստ չէ, ինչպես տոլման կամ խաշը։ Երևանում այն մատուցում են հիմնականում այն ճաշարաններում, որոնք բացահայտ արևմտահայ կամ միջինարևելյան-հայկական են՝ Բեյրութից ու Հալեպից եկած ընտանիքների հիմնած կամ Այնթապի անունը կրող վայրերում։ Ուտեստը Հայաստան է եկել հիմնականում սփյուռքի վերադարձի հետ, ոչ թե ժառանգվել է տեղում։",
