        "Սա նաև բաժնի ամենավառ օրինակն է այն բանի, թե ինչպես է ընդհանուր ուտեստը դառնում ինքնատիպ ոչ թե բաղադրիչների, այլ պատրաստման շնորհիվ։ Մանթիի մեջ ինքնին հայկական ոչինչ չկա. խմորը ցորեն ու ջուր է, լցոնը՝ աղացած գառան միս, անունը եկել է արևելքից։ Հայկականն այն որոշումն է, որ ծրարը թողնեն բաց ու դնեն վառարան, իսկ հետո թխվածի վրա լցնեն արգանակ ու սխտորով մածուն։ Տեխնիկական այս փոքր տարբերությունը բոլորովին այլ ուտեստ է ստեղծում։ Այն արժե պաշտպանել նույնքան խնամքով, որքան ցանկացած ծագման պնդում, նույնիսկ ավելի խնամքով, որովհետև, ի տարբերություն ծագման պնդումների, այն իսկապես կարելի է ցույց տալ։",
